import subprocess
import time
import glob as globmod

import sirilpy as s


def connect_siril():
    siril = s.SirilInterface()
    siril.connect()
    return siril


def run_cmd(siril, *args):
    try:
        siril.cmd(*args)
        return True
    except Exception as e:
        cmd_str = " ".join(str(a) for a in args)
        siril.log(f"[ERROR] Command failed: {cmd_str} — {e}")
        return False


def log(siril, msg):
    siril.log(f"[astro-pipeline] {msg}")
    print(f"[astro-pipeline] {msg}")


def run_external(cmd_args, timeout=600):
    cmd_str = " ".join(str(a) for a in cmd_args)
    print(f"[astro-pipeline] Running: {cmd_str}")
    start = time.time()
    result = subprocess.run(
        cmd_args,
        capture_output=True,
        text=True,
        timeout=timeout,
    )
    elapsed = time.time() - start
    if result.returncode != 0:
        print(f"[astro-pipeline] External tool failed ({elapsed:.1f}s): {result.stderr}")
        raise RuntimeError(f"External command failed: {cmd_str}\n{result.stderr}")
    print(f"[astro-pipeline] Done ({elapsed:.1f}s)")
    if result.stdout.strip():
        print(result.stdout.strip())
    return result


def find_master_dark(master_dark_dir, master_dark_file=""):
    if master_dark_file and os.path.isfile(master_dark_file):
        return master_dark_file
    if master_dark_file:
        candidate = os.path.join(master_dark_dir, master_dark_file)
        if os.path.isfile(candidate):
            return candidate

    fits_patterns = ["*.fit", "*.fits", "*.fts"]
    candidates = []
    for pat in fits_patterns:
        candidates.extend(globmod.glob(os.path.join(master_dark_dir, pat)))

    if not candidates:
        raise FileNotFoundError(
            f"No master dark found in {master_dark_dir}. "
            "Place a master dark FITS file there or set master_dark_file in config."
        )

    if len(candidates) == 1:
        return candidates[0]

    candidates.sort(key=os.path.getmtime, reverse=True)
    return candidates[0]


def ensure_dir(path):
    os.makedirs(path, exist_ok=True)


def cleanup_dir(path):
    if not os.path.isdir(path):
        return 0
    import shutil
    count = sum(len(files) for _, _, files in os.walk(path))
    shutil.rmtree(path)
    return count


def format_duration(seconds):
    m, sec = divmod(int(seconds), 60)
    h, m = divmod(m, 60)
    if h:
        return f"{h}h {m}m {sec}s"
    if m:
        return f"{m}m {sec}s"
    return f"{sec}s"
